class Solution {
    public int countPrimeSetBits(int left,int right){
        Set<Integer> primes=Set.of(2,3,5,7,11,13,17,19);
        int answer=0;
        for(int value=left;value<=right;value++)if(primes.contains(Integer.bitCount(value)))answer++;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun countPrimeSetBits(left:Int,right:Int):Int{
        val primes=setOf(2,3,5,7,11,13,17,19);
        var answer=0;
        for(value in left..right)if(Integer.bitCount(value) in primes)answer++;
        return answer
    }
}

